import React from "react";
import { Link, useLocation } from "react-router-dom";

 function Navbar() {
  const location = useLocation(); // لمعرفة الصفحة الحالية لتغيير لون الرابط

  return (
    <nav className="bg-pink-700 text-white px-6 py-4 shadow-lg flex justify-between items-center">
      {/* شعار الموقع */}
      <div className="text-2xl font-bold tracking-wide">
        💗 Breast Cancer Detection
      </div>

      {/* روابط الصفحات */}
      <div className="flex gap-6 text-lg">
        <Link
          to="/"
          className={`hover:text-pink-200 ${
            location.pathname === "/" ? "underline text-pink-200" : ""
          }`}
        >
          الرئيسية
        </Link>

        <Link
          to="/samples"
          className={`hover:text-pink-200 ${
            location.pathname === "/samples" ? "underline text-pink-200" : ""
          }`}
        >
          إدخال العينات
        </Link>

        <Link
          to="/features"
          className={`hover:text-pink-200 ${
            location.pathname === "/features" ? "underline text-pink-200" : ""
          }`}
        >
          إدخال الخصائص
        </Link>

        <Link
          to="/results"
          className={`hover:text-pink-200 ${
            location.pathname === "/results" ? "underline text-pink-200" : ""
          }`}
        >
          النتائج
        </Link>
      </div>
    </nav>
  );
}
export default Navbar;
